import {readFileSync,writeFileSync} from 'node:fs';
import {minify} from 'terser';

/** Canonical readable sources stay in tools; public scripts and the offline ZIP share identical generated bytes. */
export async function buildPhysicsRuntime(){
  for(const file of ['campo.js','exam.js','demo.js','urti.js']){
    const source=readFileSync('tools/physics-runtime/'+file,'utf8');
    const result=await minify(source,{ecma:2022,compress:true,mangle:true,format:{comments:false,preamble:'/* Generated from tools/physics-runtime/'+file+'; edit that source. */'}});
    if(!result.code)throw Error('Empty generated physics runtime: '+file);
    writeFileSync('apps/web/public/fisica/'+file,result.code+'\n');
  }
}
